import numpy as np
from scipy.optimize import linprog

def solve_for_n_with_k_l(n, k, l):
    num_vars = n*n + 1
    c_vec = [0] * (n*n) + [-1]
    A_eq = []
    b_eq = []
    for i in range(1, n+1):
        row = [0] * num_vars
        for j in range(1, n+1):
            row[(i-1)*n + (j-1)] = 1
        if i <= k:
            row[-1] = -(n-k)/k
        else:
            row[-1] = 1
        A_eq.append(row)
        b_eq.append(0)
    for j in range(1, n+1):
        row = [0] * num_vars
        for i in range(1, n+1):
            row[(i-1)*n + (j-1)] = 1
        if j <= l:
            row[-1] = -(n-l)/l
        else:
            row[-1] = 1
        A_eq.append(row)
        b_eq.append(0)
    bounds = [(-1, 1)] * (n*n) + [(0, n)]
    res = linprog(c_vec, A_eq=A_eq, b_eq=b_eq, bounds=bounds, method='highs')
    return res.x[-1] if res.success else 0

for n in [3, 5, 7, 9]:
    max_c = 0
    for k in range(1, n):
        for l in range(1, n):
            max_c = max(max_c, solve_for_n_with_k_l(n, k, l))
    print(f"n={n}, max_C={max_c}")

